/* symtpl.c: x-part candidates for the symmetric Balonin-form orthogonal designs of search/symod_join.py.
 *
 * usage: symtpl t "h1,h2" mu xsub out.bin masks.bin
 *
 * H (odd order, generated by h1, h2, ...) acts on Z_t.  Block A is symmetric: its variables are the pairs of opposite
 * H-orbits (same value on both) and the orbit {0}; blocks B and D have one variable per H-orbit.  A candidate is a
 * ternary assignment of the variables, restricted to the subgroup of order xsub (0: no restriction), of weight
 * <= mu (A, D) or <= mu / 2 (B).  Its vector is its PAF at the pair-orbit representatives (the order of odmc.c)
 * followed by its weight.  out.bin is a join4x input with the lists A, 2B, D, {0} and the target (0, ..., 0, mu), so
 * that join4x finds PAF_A + 2 PAF_B + PAF_D = 0 off the peak with w_A + 2 w_B + w_D = mu.  masks.bin holds, for each
 * of the three lists, int32 n and then n pairs of uint64 (plus mask, minus mask) over the variables, followed by the
 * variable tables (int32 nv, then per variable the representative of each of its orbits).
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAXT 2048
#define MAXV 64
#define MAXR 64
static int t, nH, Hel[MAXT], orb[MAXT], norb, orep[MAXT], osz[MAXT];
static int prep[MAXR], npr;
static int nv, vorb[MAXV][2], vlen[MAXV], vsize[MAXV];
static int Dg[MAXV][MAXR], Cx[MAXV][MAXV][MAXR];
static int wmax;
static int16_t *vbuf; static uint64_t *mbuf; static long cnt, cap;
static int val[MAXV];
static int scale;

static void emit(int *P, int w) {
    if (cnt == cap) {
        cap = cap ? 2 * cap : 1 << 16;
        vbuf = realloc(vbuf, sizeof(int16_t) * (npr + 1) * cap);
        mbuf = realloc(mbuf, sizeof(uint64_t) * 2 * cap);
        if (!vbuf || !mbuf) { fprintf(stderr, "out of memory\n"); exit(1); }
    }
    uint64_t pl = 0, mi = 0;
    for (int j = 0; j < nv; j++) { if (val[j] > 0) pl |= 1ULL << j; else if (val[j] < 0) mi |= 1ULL << j; }
    for (int k = 0; k < npr; k++) vbuf[cnt * (npr + 1) + k] = (int16_t)(scale * P[k]);
    vbuf[cnt * (npr + 1) + npr] = (int16_t)(scale * w);
    mbuf[2 * cnt] = pl; mbuf[2 * cnt + 1] = mi;
    cnt++;
}

static void dfs(int j, int w, int *P) {
    if (j == nv) { emit(P, w); return; }
    val[j] = 0;
    dfs(j + 1, w, P);
    if (w + vsize[j] > wmax) return;
    int P2[MAXR];
    for (int s = 0; s < 2; s++) {
        int v = s ? -1 : 1;
        for (int k = 0; k < npr; k++) {
            int d = Dg[j][k];
            for (int i = 0; i < j; i++) if (val[i]) d += v * val[i] * Cx[j][i][k];
            P2[k] = P[k] + d;
        }
        val[j] = v;
        dfs(j + 1, w + vsize[j], P2);
    }
    val[j] = 0;
}

static int *Tk;
static void setup_vars(int sym, int xsub) {
    int step = xsub ? t / xsub : 1;
    nv = 0;
    for (int o = 0; o < norb; o++) {
        int r = orep[o];
        if (r % step) continue;
        if (sym && r != 0) {
            int oo = orb[(t - r) % t];
            if (orep[oo] < r) continue;
            vorb[nv][0] = o; vorb[nv][1] = oo; vlen[nv] = 2; vsize[nv] = osz[o] + osz[oo];
        } else {
            vorb[nv][0] = o; vlen[nv] = 1; vsize[nv] = osz[o];
        }
        if (++nv > MAXV) { fprintf(stderr, "too many variables\n"); exit(1); }
    }
    for (int j = 0; j < nv; j++) {
        for (int k = 0; k < npr; k++) {
            int d = 0;
            for (int a = 0; a < vlen[j]; a++) for (int b = 0; b < vlen[j]; b++)
                d += Tk[((size_t)vorb[j][a] * norb + vorb[j][b]) * npr + k];
            Dg[j][k] = d;
        }
        for (int i = 0; i < j; i++) for (int k = 0; k < npr; k++) {
            int c = 0;
            for (int a = 0; a < vlen[j]; a++) for (int b = 0; b < vlen[i]; b++) {
                int o1 = vorb[j][a], o2 = vorb[i][b];
                c += Tk[((size_t)o1 * norb + o2) * npr + k] + Tk[((size_t)o2 * norb + o1) * npr + k];
            }
            Cx[j][i][k] = c;
        }
    }
}

int main(int argc, char **argv) {
    if (argc < 7) { fprintf(stderr, "usage: symtpl t gens mu xsub out.bin masks.bin\n"); return 1; }
    t = atoi(argv[1]);
    int gens[16], ng = 0;
    for (char *tok = strtok(strdup(argv[2]), ","); tok; tok = strtok(0, ",")) gens[ng++] = atoi(tok);
    int mu = atoi(argv[3]), xsub = atoi(argv[4]);
    nH = 1; Hel[0] = 1;
    for (int ch = 1; ch;) {
        ch = 0;
        for (int i = 0; i < nH; i++) for (int j = 0; j < ng; j++) {
            int x = (int)((long)Hel[i] * gens[j] % t), seen = 0;
            for (int k = 0; k < nH; k++) if (Hel[k] == x) seen = 1;
            if (!seen) { Hel[nH++] = x; ch = 1; }
        }
    }
    for (int g = 0; g < t; g++) orb[g] = -1;
    norb = 0;
    for (int g = 0; g < t; g++) {
        if (orb[g] >= 0) continue;
        orep[norb] = g; osz[norb] = 0;
        for (int k = 0; k < nH; k++) { int x = (int)((long)Hel[k] * g % t); if (orb[x] < 0) { orb[x] = norb; osz[norb]++; } }
        norb++;
    }
    for (int g = 1; g < t; g++) if (orb[g] == orb[(t - g) % t]) { fprintf(stderr, "H not admissible (even order)\n"); return 1; }
    npr = 0;
    int seenp[MAXT]; memset(seenp, 0, sizeof seenp);
    for (int o = 1; o < norb; o++) {
        int r = orep[o], oo = orb[(t - r) % t];
        if (seenp[o] || seenp[oo]) continue;
        seenp[o] = seenp[oo] = 1;
        if (npr >= MAXR - 1) { fprintf(stderr, "too many pair orbits\n"); return 1; }
        prep[npr++] = r;
    }
    Tk = calloc((size_t)norb * norb * npr, sizeof(int));
    for (int x = 0; x < t; x++) for (int k = 0; k < npr; k++) Tk[((size_t)orb[x] * norb + orb[(x + prep[k]) % t]) * npr + k]++;
    FILE *fm = fopen(argv[6], "wb");
    int16_t *lv[3]; long ln[3];
    for (int b = 0; b < 3; b++) {                     /* 0 = A (symmetric), 1 = B (scaled by 2), 2 = D */
        setup_vars(b == 0, xsub);
        wmax = b == 1 ? mu / 2 : mu;
        scale = b == 1 ? 2 : 1;
        cnt = 0; cap = 0; vbuf = 0; mbuf = 0;
        int P0[MAXR] = {0};
        dfs(0, 0, P0);
        lv[b] = vbuf; ln[b] = cnt;
        int32_t n32 = (int32_t)cnt;
        fwrite(&n32, 4, 1, fm);
        fwrite(mbuf, sizeof(uint64_t), 2 * (size_t)cnt, fm);
        free(mbuf);
        int32_t nv32 = nv;
        fwrite(&nv32, 4, 1, fm);
        for (int j = 0; j < nv; j++) {
            int32_t e[2] = {orep[vorb[j][0]], vlen[j] == 2 ? orep[vorb[j][1]] : -1};
            fwrite(e, 4, 2, fm);
        }
        fprintf(stderr, "block %c: %d variables, %ld candidates\n", "ABD"[b], nv, cnt);
    }
    fclose(fm);
    FILE *f = fopen(argv[5], "wb");
    int32_t hdr[5] = {(int32_t)ln[0], (int32_t)ln[1], (int32_t)ln[2], 1, npr + 1};
    fwrite(hdr, 4, 5, f);
    int16_t T[MAXR + 1]; memset(T, 0, sizeof T); T[npr] = (int16_t)mu;
    fwrite(T, 2, npr + 1, f);
    for (int b = 0; b < 3; b++) fwrite(lv[b], sizeof(int16_t), (size_t)ln[b] * (npr + 1), f);
    int16_t Z[MAXR + 1]; memset(Z, 0, sizeof Z);
    fwrite(Z, 2, npr + 1, f);
    fclose(f);
    fprintf(stderr, "pair orbits %d\n", npr);
    return 0;
}
